create table xxcus.xxfnd_integration_endpoints (
    endpoint_code            varchar2(30 byte) not null enable,
    endpoint_name            varchar2(200 byte) not null enable,
    endpoint_type            varchar2(30 byte) not null enable,
    base_url                 varchar2(1000 byte) not null enable,
    web_credential_static_id varchar2(255 byte),
    oauth_token_url          varchar2(1000 byte),
    oauth_scope              varchar2(1000 byte),
    status_code              varchar2(20 byte) default 'REGISTERED' not null enable,
    description              varchar2(1000 byte),
    created_by               varchar2(255 byte) not null enable,
    creation_date            timestamp(6) not null enable,
    last_updated_by          varchar2(255 byte) not null enable,
    last_update_date         timestamp(6) not null enable,
    last_update_login        varchar2(255 byte),
    object_version_number    number default 1 not null enable
);

alter table xxcus.xxfnd_integration_endpoints
    add constraint xxfnd_int_endpoints_ck1
        check ( status_code in ( 'REGISTERED', 'ACTIVE', 'INACTIVE' ) ) enable;

alter table xxcus.xxfnd_integration_endpoints
    add constraint xxfnd_int_endpoints_pk primary key ( endpoint_code )
        using index enable;


